function timeToMinutes(value) {
  const clean = normalizeTime(value);
  if (!clean) return 24 * 60 + 1;
  const parts = clean.split(":").map(Number);
  return parts[0] * 60 + parts[1];
}












function parseTaskSchedule(title, fallbackHint, overrides) {
  const options = overrides && typeof overrides === "object" ? overrides : {};
  const combined = [title, fallbackHint].filter(Boolean).join(" ");
  const parsedTime = parseTimeFromText(combined);
  const startTime = normalizeTime(options.startTime || parsedTime.startTime || "");
  const endTime = normalizeTime(options.endTime || parsedTime.endTime || (startTime ? addMinutesToTime(startTime, 45) : ""));
  return {
    day: cleanLine(options.day || parseDateFromText(combined) || todayKey()),
    startTime,
    endTime,
    dateHint: cleanLine(fallbackHint || "")
  };
}














// S1.2: подсветка совпавших букв в результатах командной палитры (донор-идея AFFiNE
// quicksearch highlight, своя реализация под наш локальный exact/fuzzy матчинг - их
// компонент рассчитан на пред-токенизированный текст с сервера). Exact substring
// подсвечивается целиком; иначе - посимвольно по порядку fuzzy-совпадения.
function highlightMatch(text, query) {
  const raw = String(text || "");
  const q = String(query || "").trim();
  if (!q) return escapeHtml(raw);
  const lowerRaw = raw.toLowerCase();
  const lowerQuery = q.toLowerCase();
  const exactIndex = lowerRaw.indexOf(lowerQuery);
  if (exactIndex >= 0) {
    return escapeHtml(raw.slice(0, exactIndex))
      + "<mark>" + escapeHtml(raw.slice(exactIndex, exactIndex + q.length)) + "</mark>"
      + escapeHtml(raw.slice(exactIndex + q.length));
  }
  let qi = 0;
  let html = "";
  for (const char of raw) {
    if (qi < lowerQuery.length && char.toLowerCase() === lowerQuery[qi]) {
      html += "<mark>" + escapeHtml(char) + "</mark>";
      qi += 1;
    } else {
      html += escapeHtml(char);
    }
  }
  return html;
}



// Расшифровка приходит РАЗБИТОЙ ПО ПАУЗАМ говорящего: whisper отдаёт каждый сегмент отдельной
// строкой. Это единственные границы смысла, которые есть у надиктованной речи — знаков препинания
// в ней часто нет вовсе. Раньше текст прогонялся через cleanLine, который схлопывает любые
// пробельные символы, включая переводы строк, — и двести слов превращались в одну строку, а
// значит в одну задачу с названием во весь экран. Здесь чистится каждая строка, а сами границы
// сохраняются.
function cleanTranscript(value) {
  return String(value == null ? "" : value)
    .split(/\r?\n/)
    .map((line) => line.replace(/[ \t]+/g, " ").trim())
    .filter(Boolean)
    .join("\n");
}





function hashString(value) {
  let hash = 2166136261;
  const text = String(value);
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function ghostIdForTitle(title) {
  return "ghost_" + hashString(normalizeTitle(title));
}



function bytesToBase64(bytes) {
  let binary = "";
  for (let index = 0; index < bytes.length; index += 8192) {
    const slice = bytes.subarray(index, index + 8192);
    binary += String.fromCharCode.apply(null, Array.from(slice));
  }
  return btoa(binary);
}

function base64ToBytes(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

// Срок сжатия обязан зависеть от размера снимка. Раньше он был жёстким — 1,8 секунды на любой
// объём, — и это работало ровно до тех пор, пока хранилище было маленьким. Как только запись
// разрослась (или машина оказалась занята), gzip перестал укладываться, снимок сохранялся сырым
// JSON, от этого рос ещё сильнее, следующее сжатие срывалось раньше — и так по спирали, с
// потоком предупреждений в консоли. Владелец увидел итог этой спирали как экран «Repository
// boundary stopped a failure» на своей вкладке. Бюджет считаем от объёма: ~2 мс на килобайт,
// не меньше прежних 1,8 с и не больше 30 с, чтобы зависание всё ещё ловилось.
function streamBudgetMs(length) {
  return Math.min(30000, Math.max(1800, Math.round((Number(length) || 0) / 1024) * 2));
}

async function compressText(text) {
  if ("CompressionStream" in window) {
    try {
      return await withTimeout(async () => {
        const stream = new CompressionStream("gzip");
        const writer = stream.writable.getWriter();
        await writer.write(new TextEncoder().encode(text));
        await writer.close();
        const buffer = await new Response(stream.readable).arrayBuffer();
        return {
          encoding: "gzip-base64",
          payload: bytesToBase64(new Uint8Array(buffer))
        };
      }, streamBudgetMs(text.length));
    } catch (error) {
      console.warn("CompressionStream fallback", error);
    }
  }
  return {
    encoding: "json",
    payload: text
  };
}

async function decompressText(encoding, payload) {
  if (encoding === "gzip-base64" && "DecompressionStream" in window) {
    try {
      return await withTimeout(async () => {
        const bytes = base64ToBytes(payload);
        const stream = new DecompressionStream("gzip");
        const writer = stream.writable.getWriter();
        await writer.write(bytes);
        await writer.close();
        return new Response(stream.readable).text();
      }, streamBudgetMs(payload.length));
    } catch (error) {
      console.warn("DecompressionStream fallback", error);
    }
  }
  return payload;
}

function withTimeout(factory, timeoutMs) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("stream timeout")), timeoutMs);
    factory().then((value) => {
      clearTimeout(timer);
      resolve(value);
    }).catch((error) => {
      clearTimeout(timer);
      reject(error);
    });
  });
}

function idbRequest(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function idbTransaction(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve(true);
    transaction.onerror = () => reject(transaction.error);
    transaction.onabort = () => reject(transaction.error || new Error("IndexedDB transaction aborted"));
  });
}

class KnowledgeRepository {
  constructor() {
    this.db = null;
    this.storageMode = "IndexedDB";
    this.lastPayloadBytes = 0;
    this.lastChunkCount = 0;
    this.lastEncoding = "json";
  }

  async init() {
    if (!("indexedDB" in window)) {
      this.storageMode = "localStorage fallback";
      return;
    }
    try {
      this.db = await new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onupgradeneeded = () => {
          const db = request.result;
          if (!db.objectStoreNames.contains(STORE_NAME)) {
            db.createObjectStore(STORE_NAME, { keyPath: "id" });
          }
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
        request.onblocked = () => reject(new Error("IndexedDB upgrade blocked"));
      });
    } catch (error) {
      this.db = null;
      this.storageMode = "localStorage fallback";
      console.warn(error);
    }
  }

  async load() {
    if (this.db) {
      const meta = await this.readRecord(META_KEY);
      if (meta && Number.isFinite(meta.chunkCount)) {
        const parts = [];
        for (let index = 0; index < meta.chunkCount; index += 1) {
          const chunk = await this.readRecord(CHUNK_PREFIX + String(index).padStart(5, "0"));
          if (!chunk) throw new Error("Missing repository chunk " + index);
          parts.push(chunk.payload);
        }
        const payload = parts.join("");
        const text = await decompressText(meta.encoding, payload);
        this.lastPayloadBytes = meta.payloadLength || payload.length;
        this.lastChunkCount = meta.chunkCount;
        this.lastEncoding = meta.encoding;
        return normalizeState(JSON.parse(text));
      }
    }

    const fallbackMeta = localStorage.getItem(FALLBACK_PREFIX + META_KEY);
    if (fallbackMeta) {
      const meta = JSON.parse(fallbackMeta);
      const parts = [];
      for (let index = 0; index < meta.chunkCount; index += 1) {
        const key = FALLBACK_PREFIX + CHUNK_PREFIX + String(index).padStart(5, "0");
        const chunk = localStorage.getItem(key);
        if (chunk == null) throw new Error("Missing fallback chunk " + index);
        parts.push(chunk);
      }
      const payload = parts.join("");
      const text = await decompressText(meta.encoding, payload);
      this.lastPayloadBytes = meta.payloadLength || payload.length;
      this.lastChunkCount = meta.chunkCount;
      this.lastEncoding = meta.encoding;
      return normalizeState(JSON.parse(text));
    }

    return normalizeState(createInitialState());
  }

  async readRecord(id) {
    return idbRequest(this.db.transaction(STORE_NAME, "readonly").objectStore(STORE_NAME).get(id));
  }

  // Сколько в снимке того, что владелец создал сам. Заметки не считаем: часть из них приезжает
  // с заводским наполнением, и по ним пустое хранилище не отличить от заполненного.
  static ownerRecordCount(state) {
    const collections = ["sources", "tasks", "financeTransactions", "planBlocks", "goals", "habits", "claims", "highlights"];
    let total = 0;
    for (const name of collections) {
      const collection = state[name];
      if (collection && typeof collection === "object") total += Object.keys(collection).length;
    }
    return total;
  }

  // Правда о том, что уже лежит на диске, берётся из META: рядом со снимком записано, сколько
  // в нём было записей владельца. Считаем именно их, а не байты: свежее хранилище с заводским
  // наполнением весит полтораста килобайт, и по размеру пустое от полного не отличить.
  async wouldEraseVault(candidate) {
    if (!this.db) return false;
    if (KnowledgeRepository.ownerRecordCount(candidate) > 0) return false;
    let meta = null;
    try { meta = await this.readRecord(META_KEY); } catch (error) { return false; }
    if (!meta) return false;
    if (Number.isFinite(meta.ownerRecords)) return meta.ownerRecords > 0;
    // Снимок от прежних версий счётчика не несёт: там судим по размеру, консервативно.
    return Number.isFinite(meta.rawLength) && meta.rawLength > 400000;
  }

  // Тяжёлые файлы (аудио, картинки) лежат ОТДЕЛЬНО от состояния — блобом под ключом
  // `media:<sourceId>`. Раньше байты кодировались в base64 и жили внутри самого состояния, а
  // состояние целиком пишется одним снимком: файл больше 8 МБ туда не помещался, и запись
  // просто теряла звук, честно об этом сообщая. Блоб IndexedDB хранит как есть, потолка нет,
  // и снимок состояния не раздувается. Отдельного хранилища не заводим — тот же объект-стор,
  // только с префиксом ключа, поэтому версию базы поднимать не нужно.
  async writeMedia(sourceId, blob) {
    if (!this.db || !blob) return false;
    const transaction = this.db.transaction(STORE_NAME, "readwrite");
    transaction.objectStore(STORE_NAME).put({ id: MEDIA_PREFIX + sourceId, blob });
    await idbTransaction(transaction);
    return true;
  }

  async readMedia(sourceId) {
    if (!this.db) return null;
    const record = await this.readRecord(MEDIA_PREFIX + sourceId);
    return record && record.blob ? record.blob : null;
  }

  async deleteMedia(sourceId) {
    if (!this.db) return false;
    const transaction = this.db.transaction(STORE_NAME, "readwrite");
    transaction.objectStore(STORE_NAME).delete(MEDIA_PREFIX + sourceId);
    await idbTransaction(transaction);
    return true;
  }

  async save(state) {
    // Failure injection (P9.2): a test-only switch that makes the real persistence path
    // genuinely throw, so recovery behavior (in-memory state survives, other surfaces stay
    // usable, health honestly reports "failed") is proven against a real failure, not a
    // mocked-away one.
    if (this.simulateFailureForTest) throw new Error("Simulated storage failure (test injection)");
    const clean = normalizeState(state);
    // ЗАЩИТА ОТ ЗАТИРАНИЯ. Если загрузка по любой причине не прочитала снимок, приложение
    // поднимается на пустом состоянии — и первое же автосохранение затирает настоящее хранилище.
    // Так были потеряны две голосовые записи владельца и всё, что из них выросло: экран показывал
    // сбой, а фоновый коммит в это время записал поверх реальных данных пустоту. Локально-первый
    // продукт не имеет права терять данные молча: пустой снимок поверх непустого не пишется
    // никогда, а отказ виден в состоянии и в журнале.
    if (await this.wouldEraseVault(clean)) {
      this.lastSaveBlockedAt = now();
      throw new Error("Сохранение остановлено: пустое состояние поверх непустого хранилища. Данные на диске не тронуты — переоткрой вкладку.");
    }
    clean.lastSavedAt = now();
    const text = JSON.stringify(clean);
    const compressed = await compressText(text);
    const chunks = chunkString(compressed.payload, CHUNK_SIZE);
    const meta = {
      id: META_KEY,
      schemaVersion: clean.schemaVersion,
      encoding: compressed.encoding,
      chunkCount: chunks.length,
      rawLength: text.length,
      // Сколько записей владельца в этом снимке — по нему следующая запись поймёт, что затирает.
      ownerRecords: KnowledgeRepository.ownerRecordCount(clean),
      payloadLength: compressed.payload.length,
      updatedAt: clean.lastSavedAt
    };

    this.lastPayloadBytes = compressed.payload.length;
    this.lastChunkCount = chunks.length;
    this.lastEncoding = compressed.encoding;

    if (this.db) {
      await new Promise((resolve, reject) => {
        const tx = this.db.transaction(STORE_NAME, "readwrite");
        const objectStore = tx.objectStore(STORE_NAME);
        const keyRequest = objectStore.getAllKeys();
        keyRequest.onsuccess = () => {
          const keys = keyRequest.result || [];
          for (const key of keys) {
            if (key === META_KEY || String(key).startsWith(CHUNK_PREFIX)) {
              objectStore.delete(key);
            }
          }
          objectStore.put(meta);
          for (let index = 0; index < chunks.length; index += 1) {
            objectStore.put({
              id: CHUNK_PREFIX + String(index).padStart(5, "0"),
              index,
              payload: chunks[index]
            });
          }
        };
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error || new Error("Repository transaction aborted"));
      });
      return clean;
    }

    for (let index = localStorage.length - 1; index >= 0; index -= 1) {
      const key = localStorage.key(index);
      if (key && key.startsWith(FALLBACK_PREFIX)) localStorage.removeItem(key);
    }
    localStorage.setItem(FALLBACK_PREFIX + META_KEY, JSON.stringify(meta));
    for (let index = 0; index < chunks.length; index += 1) {
      localStorage.setItem(FALLBACK_PREFIX + CHUNK_PREFIX + String(index).padStart(5, "0"), chunks[index]);
    }
    return clean;
  }

  close() {
    if (this.db && typeof this.db.close === "function") {
      this.db.close();
    }
    this.db = null;
  }
}

