    entry.secretValue = String(entry.secretValue || "");
    entry.maskedPreview = cleanLine(entry.maskedPreview || (entry.secretValue ? "*".repeat(Math.max(0, entry.secretValue.length - 4)) + entry.secretValue.slice(-4) : ""));
