          label: "STT (whisper.cpp)",
          endpoint: cleanLine(endpoint),
          lastError: message,
          lastCheckedAt: now(),
          requiredAction: "whisper.cpp недоступен: " + message + ". Запусти локальный сервер (npm run whisper-server) и проверь снова."
